from django.contrib.sessions.backends.db import SessionStore
from django.contrib.messages.storage.session import SessionStorage
from django.http import JsonResponse, HttpResponseBadRequest
from django.views import View

class CrossSessionToastPollingView(View):
    def get(self, request):
        target_session_key = request.GET.get('session_key')
        if not target_session_key:
            return HttpResponseBadRequest("session_key required")

        # Directly loads another user's session store to extract flash messages
        session = SessionStore(session_key=target_session_key)
        if not session.exists(target_session_key):
            return JsonResponse({'messages': []})

        raw_messages = session.get(SessionStorage.session_key, [])
        message_list = [{'message': msg, 'level': lvl} for msg, lvl, *_ in [m.split(':', 2) for m in raw_messages if ':' in m]]
        return JsonResponse({'session_key': target_session_key, 'messages': message_list})

